'use strict';
/* 용병 그림 42장 (img 폴더 없이도 뜨도록 파일 하나에 담았어요) */
const IMGDATA = {"blade_0":"","blade_1":"","blade_2":"","chrono_0":"","chrono_1":"","chrono_2":"","eclipse_0":"","eclipse_1":"","eclipse_2":"","glitch_0":"","glitch_1":"","glitch_2":"","halo_0":"","halo_1":"","halo_2":"","hawkeye_0":"","hawkeye_1":"","hawkeye_2":"","ironwall_0":"","ironwall_1":"","ironwall_2":"","nano_0":"","nano_1":"","nano_2":"","neuro_0":"","neuro_1":"","neuro_2":"","pug_0":"","pug_1":"","pug_2":"","reaper_0":"","reaper_1":"","reaper_2":"","specter_0":"","specter_1":"","specter_2":"","swarm_0":"","swarm_1":"","swarm_2":"","volt_0":"","volt_1":"","volt_2":""};

const IMGURL = {};
(function () {
  for (const k in IMGDATA) {
    try {
      const bin = atob(IMGDATA[k]), u = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
      IMGURL[k] = URL.createObjectURL(new Blob([u], { type: 'image/webp' }));
    } catch (e) { IMGURL[k] = 'data:image/webp;base64,' + IMGDATA[k]; }
  }
})();
